ber\\\"):\",\"        if key in values:\",\"            values[key] = parse_usize(values[key], key)\",\"    if not os.path.isfile(values[\\\"inputFile\\\"]):\",\"        cli_error(\\\"'inputFile' does not exist\\\")\",\"    if \\\"passwordDictionary\\\" in values and not os.path.isfile(values[\\\"passwordDictionary\\\"]):\",\"        cli_error(\\\"'passwordDictionary' does not exist\\\")\",\"    if \\\"charsetFile\\\" in values and not os.path.isfile(values[\\\"charsetFile\\\"]):\",\"        cli_error(\\\"'charsetFile' does not exist\\\")\",\"    if values.get(\\\"workers\\\") == 0:\",\"        cli_error(\\\"'workers' must be positive\\\")\",\"    if values[\\\"minPasswordLen\\\"] == 0:\",\"        cli_error(\\\"'minPasswordLen' must be positive\\\")\",\"    if values[\\\"maxPasswordLen\\\"] == 0:\",\"        cli_error(\\\"'maxPasswordLen' must be positive\\\")\",\"    if values[\\\"minPasswordLen\\\"] > values[\\\"maxPasswordLen\\\"]:\",\"        cli_error(\\\"'maxPasswordLen' must be equal or greater than 'minPasswordLen'\\\")\",\"    custom = [None] * 4\",\"    for index in range(4):\",\"        name = f\\\"customCharset{index + 1}\\\"\",\"        if name in values:\",\"            if \\\"mask\\\" not in values:\",\"                cli_error(f\\\"'--{name}' can only be used with --mask\\\")\",\"            custom[index] = parse_custom(values[name])\",\"    values[\\\"custom\\\"] = custom\",\"    if \\\"mask\\\" in values and \\\"passwordDictionary\\\" in values:\",\"        cli_error(\\\"'mask' cannot be used with a dictionary file\\\")\",\"    if \\\"startingPassword\\\" in values:\",\"        if \\\"passwordDictionary\\\" in values:\",\"            cli_error(\\\"'startingPassword' cannot be used with a dictionary file\\\")\",\"        if \\\"mask\\\" in values:\",\"            cli_error(\\\"'startingPassword' cannot be used with mask attack\\\")\",\"        charset = get_charset(values)\",\"        if any(ch not in charset for ch in values[\\\"startingPassword\